// The one way the app talks to Beacon: a client whose paths, parameters and
// answers are typed from the OpenAPI description (schema.d.ts, generated by
// `npm run generate`). A route or a field that the API does not have does
// not compile.
import createClient, { type Middleware } from "openapi-fetch";
import type { components, paths } from "./schema";

export type Schemas = components["schemas"];

/** What the API answers when a request fails, as the app shows it. */
export class ApiError extends Error {
  readonly status: number;
  /** The part of the request at fault, when the API names one. */
  readonly field: string | undefined;

  constructor(status: number, message: string, field?: string) {
    super(message);
    this.name = "ApiError";
    this.status = status;
    this.field = field;
  }
}

let onSessionEnded: () => void = () => undefined;

/** Registers what happens when the API says that nobody is signed in. */
export function setSessionEndedHandler(handler: () => void): void {
  onSessionEnded = handler;
}

const mePath = "/api/v1/me";

// A 401 from anything but the question "who am I" means the session ended
// while the app was open: the app goes back to the sign-in page.
const sessionWatch: Middleware = {
  onResponse({ response, schemaPath }) {
    if (response.status === 401 && schemaPath !== mePath && schemaPath !== "/auth/bootstrap") {
      onSessionEnded();
    }
  },
};

// The session is a cookie that scripts cannot read; the browser sends it to
// the same origin, which is all the app ever talks to. Nothing is kept in
// browser storage.
export const api = createClient<paths>({
  baseUrl: window.location.origin,
  credentials: "same-origin",
  // Looked up at each call, so that a test can put its own in place.
  fetch: (request) => globalThis.fetch(request),
});
api.use(sessionWatch);

interface Result<T> {
  data?: T;
  error?: unknown;
  response: Response;
}

/**
 * Turns an answer into its body, or throws an ApiError that says what the
 * API said. A request that never got an answer throws one with status 0.
 */
export async function unwrap<T>(request: Promise<Result<T>>): Promise<T> {
  let result: Result<T>;
  try {
    result = await request;
  } catch (cause) {
    if (cause instanceof DOMException && cause.name === "AbortError") {
      throw cause;
    }
    throw new ApiError(0, "Beacon cannot be reached. Check your connection; this page keeps trying.");
  }
  if (result.response.ok) {
    // A 204 has no body; its callers ask for nothing.
    return result.data as T;
  }
  const body = result.error as Partial<Schemas["Error"]> | undefined;
  const message = typeof body?.error === "string" && body.error !== "" ? body.error : `The request failed (${result.response.status}).`;
  throw new ApiError(result.response.status, message, typeof body?.field === "string" ? body.field : undefined);
}

/** What to show for something that was thrown. */
export function errorMessage(error: unknown): string {
  if (error instanceof ApiError) {
    return error.message;
  }
  return "Something went wrong in the page. Reload it; if it happens again, report it.";
}
